class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        if (n <= 1) return;
        k = k % n;                    // 关键：先取模，否则 k 可能远大于 n

        for (int t = 0; t < k; t++) {
            int last = nums[n - 1];   // 先保存最后一个，否则会被覆盖
            for (int i = n - 1; i >= 1; i--) {
                nums[i] = nums[i - 1];
            }
            nums[0] = last;
        }
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;
        if (k == 0) return;

        int[] tmp = new int[n];
        for (int i = 0; i < n; i++) {
            // 原来第 i 个元素，右移 k 格后落在 (i + k) % n
            tmp[(i + k) % n] = nums[i];
        }
        // 题目要求原地修改入参，必须把 tmp 抄回去
        System.arraycopy(tmp, 0, nums, 0, n);
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;
        if (k == 0) return;

        reverse(nums, 0, n - 1);   // 整体反转
        reverse(nums, 0, k - 1);   // 前 k 个反转
        reverse(nums, k, n - 1);   // 剩下 n-k 个反转
    }

    // 闭区间 [l, r] 原地反转
    private void reverse(int[] nums, int l, int r) {
        while (l < r) {
            int t = nums[l];
            nums[l] = nums[r];
            nums[r] = t;
            l++;
            r--;
        }
    }
}
